// Русский (Россия) UI catalog — partial by design (owner 2026-10-13: periodic translation; normal
// development maintains only zh-CN + en). Missing keys fall back to en at lookup time
// (i18n/index.tsx); `...modulesEn` first keeps every key present, the entries below override.
//
// Глоссарий (пополнение 2026-10-15, к 100 % покрытия; ранее устоявшиеся термины: среда выполнения
// = runtime, ход = turn, партнёр = peer, делегирование = delegation, хост = host, профиль =
// Profile, быстрый запуск = quick launch, усилие = effort, квота = quota, возможности =
// capabilities):
// workflow → рабочий процесс; run plan → план запуска; orchestration script → сценарий
// оркестрации; job → задание (Job Service / Task Service — служебные имена, латиницей);
// skill → навык; hook → хук; usage limit → лимит использования; backend → бэкенд (обновления
// бэкенда = backend updates); release → релиз; rollback → откат / откачено; one-way update →
// необратимое обновление; preflight → предпроверка; batch → партия; side chat → боковой чат;
// display name → отображаемое имя; endpoint → эндпоинт; price mapping → сопоставление цен;
// extra directories (usage) → дополнительные каталоги.
