  "claude-science.form.homeHint": "HOME аккаунта, создаётся при отсутствии. Существующий каталог сохранит уже выполненный вход (сначала остановите этот аккаунт везде, где он работает). Не более 41 символа (ограничение Claude Science). Удаление аккаунта никогда его не удаляет.",
  "claude-science.form.binary": "Программа Claude Science (на хосте)",
  "claude-science.form.portHint": "Пусто: выбирается свободный порт",
  "claude-science.form.sshHint": "Кладёт в каталог аккаунта ссылку на ~/.ssh пользователя хоста, чтобы Claude мог использовать ваши SSH-ключи и конфигурацию для доступа к удалённым машинам. Существующий там .ssh не трогается.",
  "claude-science.form.submit": "Добавить и запустить",
  "claude-science.problem.id": "ID: 1–12 строчных букв, цифр или -, не начинается и не заканчивается на -",
  "claude-science.problem.idTaken": "Аккаунт с таким ID уже существует",
  "claude-science.problem.home": "Каталог аккаунта: ~, ~/… или абсолютный путь, без .., абсолютный путь не длиннее 41 символа",
  "claude-science.problem.binary": "Путь к программе: ~/… или абсолютный путь",
  "claude-science.needsBrowser": "Для открытия нужен модуль браузера: включите его в Настройки → Модули и попробуйте снова",
  "claude-science.otherHost": "Аккаунты этого хоста открываются во вкладке его браузера: сначала откройте одного из {{agents}} этого хоста, затем снова нажмите «Открыть»",
  "claude-science.login.title": "Первый вход",
  "claude-science.login.step1": "Нажмите «Открыть»: встроенный браузер открывает аккаунт на локальной странице входа Claude Science (одноразовая ссылка, создаётся заново при каждом открытии). Нажмите Sign in.",
  "claude-science.login.step2": "Внутри нажмите Sign in on the web и войдите в этот аккаунт на claude.ai. Если claude.ai показывает другой аккаунт, сначала переключитесь или выйдите; этот шаг можно выполнить и в другом браузере, где выполнен вход в этот аккаунт.",
  "claude-science.login.step3": "Затем claude.ai покажет код авторизации: скопируйте его и вставьте в Claude Science (Paste code).",
  "claude-science.login.step4": "Claude Science один раз перезапустится сам (это ожидаемо; cutex его отслеживает). Аккаунт останется в системе; при следующих открытиях нажимайте Sign in или Continue.",
  "claude-science.login.why": "Каждый аккаунт входит один раз в своём каталоге, а не через вход Claude профиля cutex: общий вход заставил бы токены обновления выталкивать друг друга.",
  "claude-science.previewNote": "HTML-предпросмотры, созданные Claude, загружаются с другого локального порта хоста: видны, когда десктоп работает на том же хосте, с удалённого хоста — нет.",
  "codex-config.description": "Плагины Codex, MCP-серверы, навыки и хуки",
  "codex-config.mcp.builtin.job": "Инструменты Job Service (фоновые задания / песочница); внедряются, только если на хосте есть Job Service. Инструменты только для чтения работают напрямую, остальные — через обычное подтверждение",
  "codex-config.plugins.needsCutex": "Обновите cutex, чтобы управлять плагинами здесь",
  "codex-config.plugins.applies": "Codex {{agents}} загружают включённые плагины при запуске, работающие — после перезапуска; Claude {{agents}} их не загружают",
  "codex-config.plugins.warning": "Плагины запускают процессы, используют сеть и выполняют команды внутри каждого Codex {{agent}}: устанавливайте только доверенные источники",
  "codex-config.plugins.followHint": "Вкл.: Codex {{agents}} применяют общие плагины, MCP, навыки и доверие хуков при запуске (собственные дополнения сохраняются); выкл.: остаются на снимке с момента создания",
  "codex-config.skills.archiveArmed": "Нажмите ещё раз, чтобы заархивировать",
  "codex-config.skills.archivedHint": "Заархивированные навыки переезжают в archive/skills в домашнем каталоге cutex; {{agents}} перестают их видеть со следующего запуска. Восстановление возвращает их на место",
  "codex-config.skills.error.nameTaken": "На прежнем месте уже есть навык с таким именем; сначала заархивируйте или переименуйте его",
  "codex-config.skills.error.notArchivable": "Архивировать можно только пользовательские навыки; системные, административные и плагинные нельзя",
  "nci.pageHint": "Задания, отправляемые {{agents}} в NCI Gadi, появляются на странице «Задачи», а отправившему {{agent}} сообщается об их завершении; выполните шаги ниже",
  "notes.emptyHint": "Используйте 「Добавить заметку к этому ходу」 в панели действий ответа или 「Новая заметка」 выше.",
  "notifications.preset.legacyNote": "cutex этого хоста старее и всё ещё ведёт себя по-старому; выберите пресет, чтобы переключить. Более новые cutex этого больше не предлагают",
