  "workSurface.widthRules": "Умная (по умолчанию): одна рабочая область — по содержимому, две — на всё окно; разговоры делят ширину в пропорции, которую вы задали последней. По содержимому: колонка разговора и её {{shelf}} сохраняют собственную ширину и центрируются вместе, по бокам виден рабочий стол. На всё окно: колонки делят всю ширину окна. Здесь задаётся только ширина; карточки сохраняют скругления, промежутки и тени (режим «от края до края» настраивается отдельно ниже). Перетаскивание границы между двумя панелями меняет только эти две; двойной щелчок возвращает их ширину по умолчанию; смена фокуса никогда не меняет раскладку",
