  "browser.externalUnavailable": "Этот адрес нельзя открыть во встроенном браузере.",
  "browser.refusal.externalOff": "Веб-сайты выключены (Настройки → Браузер → Разрешить веб-сайты).",
  "browser.refusal.proxyUnavailable": "Веб-сайты включены, но интернет-прокси браузера ещё не готов (или только что остановился).",
  "browser.refusal.privateAddress": "Страницы и {{agents}} не могут сами обращаться к адресам локальной сети, tailnet или локальным адресам; введите адрес в адресной строке сами, чтобы открыть его в этой вкладке.",
  "browser.refusal.reservedAddress": "Это link-local или зарезервированный адрес (например, 169.254.x.x, 127.0.0.2, *.localhost); встроенный браузер никогда его не открывает.",
  "browser.refusal.protectedEndpoint": "Это управляющий порт cutex (управление, шина сообщений или прокси браузера); встроенный браузер никогда его не открывает.",
  "browser.refusal.remoteLoopback": "Этот хост подключён по SSH: этот адрес находится на вашем компьютере, а не на удалённом хосте. Для удалённого сервиса используйте ссылку cutex:service/ хоста; подтверждайте, только если действительно нужна локальная страница.",
  "browser.refusal.openDesktopLoopback": "Открыть этот адрес на этом компьютере",
  "browser.desktopLoopback.title": "Локальные страницы во вкладках SSH-хостов",
  "browser.desktopLoopback.label": "Запомнить: разрешить владельцу переходы на локальный loopback",
  "browser.desktopLoopback.hint": "По умолчанию выключено и запоминается отдельно для этого SSH-хоста. Открываются только введённые или явно подтверждённые вами адреса localhost / 127.0.0.1 / ::1; агенты и другие страницы не получают локальный доступ, а порты управления cutex всегда заблокированы.",
  "browser.desktopLoopback.badge": "Этот компьютер",
  "browser.desktopLoopback.badgeHint": "Эта страница находится на компьютере с Cutex, а не на текущем SSH-хосте.",
  "browser.desktopLoopback.noAgent": "Страницами на этом компьютере нельзя делиться.",
  "browser.refusal.enableExternal": "Включить веб-сайты",
  "browser.refusal.retry": "Повторить",
  "browser.refusal.forced": "Переменная окружения режима разработки принудительно выключает веб-сайты; здесь их включить нельзя.",
  "browser.controlPaused": "Приостановлено · нажмите «Продолжить», чтобы возобновить",
  "browser.externalPages.hint": "Когда включено, вкладки встроенного браузера выходят в интернет через локальный прокси только для браузера (только 127.0.0.1, новые учётные данные при каждом запуске, без расшифровки HTTPS, без кэша; закрывается вместе с последней вкладкой или при выходе из приложения). Пользоваться им могут только вкладки браузера: окно приложения, плагины и страницы артефактов по-прежнему без сети. Выключение сразу обрывает открытые соединения с веб-сайтами. Адреса локальной сети / tailnet не зависят от этого переключателя: адрес, открытый в адресной строке, работает только в этой вкладке, а страницы не могут сами обращаться к другим адресам локальной сети или локальным адресам.",
  "browser.blocked.popup": "Заблокировано окно, которое страница пыталась открыть сама. Нажмите ссылку или кнопку на странице, чтобы открыть его в новой вкладке.",
  "browser.blocked.download": "Заблокирована загрузка, которую страница начала сама. Нажатие на ссылку загрузки открывает диалог сохранения.",
  "browser.blocked.downloadHidden": "Загрузка от {name} отменена: окно не видно, поэтому вы не могли выбрать, куда сохранить файл.",
  "browser.blocked.permissionWaiting": "{origin} хочет использовать {permissions}: выберите «Разрешить» или «Блокировать» в системном диалоге над окном Cutex (его может закрывать другое окно). Страница ждёт вашего ответа.",
  "browser.blocked.permissionHidden": "{origin} хочет использовать {permissions}, но окно Cutex свёрнуто или скрыто, поэтому спросить вас было нельзя: на этот раз заблокировано, ничего не запомнено. Покажите окно и повторите попытку на странице.",
  "browser.blocked.permissionTimeout": "{origin} хотел использовать {permissions} и не получил ответа за 2 минуты: на этот раз заблокировано, ничего не запомнено. Повторная попытка на странице снова вызовет запрос.",
  "browser.newTab.agent": "Щелчок {name} открыл новую вкладку. Управлять ею он не может, пока вы её не передадите.",
  "browser.newTab.agentGranted": "Щелчок {name} открыл новую вкладку; он продолжает работать в ней с разрешением исходной вкладки. Его можно приостановить или отозвать в любой момент.",
  "browser.sitePermissions.title": "Разрешения сайтов",
  "browser.sitePermissions.hint": "Когда странице нужны камера, микрофон, местоположение и т. п., приложение спрашивает вас и выдаёт разрешение только этому сайту (точному источнику); ни {{agents}}, ни страницы не могут ответить за вас. Здесь перечислены решения, для которых вы отметили «Запомнить». Доступ к устройствам (USB, последовательный порт, HID, Bluetooth), демонстрация экрана и полноэкранный режим не предлагаются.",
  "browser.sitePermissions.empty": "Запомненных разрешений сайтов пока нет.",
  "browser.sitePermissions.allowed": "Разрешено",
  "browser.sitePermissions.blocked": "Заблокировано",
  "browser.sitePermissions.agentPool": "Пул входов {{agents}}",
