  "browser.sitePermission.waiting": "{origin} хочет использовать {permissions}: выберите «Разрешить» или «Блокировать» в системном диалоге; страница ждёт вашего ответа. Диалог находится над окном Cutex (вернитесь в Cutex, если он закрыт); без ответа в течение 2 минут доступ блокируется, ничего не запоминается.",
